function [MRSCont] = OspreyProcess(MRSCont)
%% [MRSCont] = OspreyProcess(MRSCont)
%   This function pre-processes MRS data from all major vendors.
%   Data is read from the provided input filenames. It is shaped,
%   preprocessed, aligned, etc. according to the type of sequence
%   (un-edited data, MEGA-edited (ON/OFF), HERMES/HERCULES (A/B/C/D),
%   etc.).
%
%   USAGE:
%       MRSCont = OspreyProcess(MRSCont);
%
%   INPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   OUTPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   AUTHOR:
%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-02-19)
%       goeltzs1@jhmi.edu
%
%   CREDITS:
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2019-02-19: First version of the code.

outputFolder = MRSCont.outputFolder;
diary(fullfile(outputFolder, 'LogFile.txt'));

% Checking for version, toolbox, and previously run modules
[~,MRSCont.ver.CheckOsp ] = osp_CheckRunPreviousModule(MRSCont, 'OspreyProcess');


%% Data post-processing starts here
warning('off','all');

% Loop over all datasets
refProcessTime = tic;
if MRSCont.flags.isGUI
    progressText = MRSCont.flags.inProgress;
else
    progressText = '';
end

for kk = 1:MRSCont.nDatasets(1) %Subject loop
    for ll = 1: 1:MRSCont.nDatasets(2) %Experiment loop
        [~] = printLog('OspreyProcess',kk,ll,MRSCont.nDatasets(1),progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);


        if ~(MRSCont.flags.didProcess == 1 && MRSCont.flags.speedUp && isfield(MRSCont, 'processed') && (kk > size(MRSCont.processed.metab,2)))  || ~strcmp(MRSCont.ver.Osp,MRSCont.ver.CheckOsp)
            metab_ll = MRSCont.opts.MultipleSpectra.metab(ll);
%%          %%% 1. GET RAW DATA %%%
            raw                         = MRSCont.raw{metab_ll,kk};                                          % Get the kk-th dataset

            % Get sequence type set up
            if raw.flags.isUnEdited
                seq = 'unedited';
            elseif raw.flags.isMEGA
                seq = 'MEGA';
            elseif raw.flags.isHERMES
                seq = 'HERMES';
            elseif raw.flags.isHERCULES
                seq = 'HERCULES';
            end

%%          %%% 1B. GET MM DATA %%%
            if MRSCont.flags.hasMM
                mm_ll = MRSCont.opts.MultipleSpectra.mm(ll);
                raw_mm                         = MRSCont.raw_mm{mm_ll,kk};              % Get the kk-th dataset re_mm
                if raw_mm.averages > 1 && raw_mm.flags.averaged == 0 %re_mm
                    [raw_mm,fs,phs]               = op_alignAverages(raw_mm, 1, 'n'); %re_mm
                    raw_mm                     = op_averaging(raw_mm);            % Average re_mm
                else %re_mm
                    raw_mm.flags.averaged  = 1; %re_mm
                    raw_mm.dims.averages   = 0; %re_mm
                    fs = 0;
                    phs = 0;
                end
                if raw_mm.flags.isUnEdited
                    [raw_mm,~]                     = op_ppmref(raw_mm,4.6,4.8,4.68);  % Reference to water @ 4.68 ppm  %re_mm
                end
                if raw_mm.flags.isUnEdited
                    raw_mm.names = {'A'};
                    raw_mm.target = {''};
                    raw_mm.specReg{1}.fs              = fs; % save align parameters
                    raw_mm.specReg{1}.phs             = phs; % save align parameters
                    raw_mm.specReg{1}.weights{1}         = ones(size(phs)); % save align parameters
                    driftPre = 0;
                end
                if raw_mm.flags.isMEGA
                    raw_mm.names = {'A','B'};
                    raw_mm.target = MRSCont.opts.editTarget';
                    raw_mm.specReg{1}.fs              = fs; % save align parameters
                    raw_mm.specReg{1}.phs             = phs; % save align parameters
                    raw_mm.specReg{1}.weights{1}         = ones(size(phs)); % save align parameters
                    raw_mm.specReg{1}.weights{2}         = ones(size(phs)); % save align parameters
                    driftPre{1} = 0;
                    driftPre{2} = 0;
                end
                if raw_mm.flags.isHERMES || raw_mm.flags.isHERCULES
                    raw_mm.names = {'A', 'B', 'C', 'D'};
                    raw_mm.target = MRSCont.opts.editTarget';
                    raw_mm.specReg{1}.fs              = fs; % save align parameters
                    raw_mm.specReg{1}.phs             = phs; % save align parameters
                    raw_mm.specReg{1}.weights{1}         = size(phs); % save align parameters
                    raw_mm.specReg{1}.weights{2}         = size(phs); % save align parameters
                    raw_mm.specReg{1}.weights{3}         = size(phs); % save align parameters
                    raw_mm.specReg{1}.weights{4}         = size(phs); % save align parameters
                    driftPre{1} = 0;
                    driftPre{2} = 0;
                    driftPre{3} = 0;
                    driftPre{4} = 0;
                end
            end  %re_mm

%%          %%% 1C. GET MM REFERENCE DATA %%%
            if MRSCont.flags.hasMMRef
                mm_ref_ll = MRSCont.opts.MultipleSpectra.mm_ref(ll);
                raw_mm_ref = MRSCont.raw_mm_ref{mm_ref_ll,kk};              % Get the kk-th dataset
                raw_mm_ref = op_combine_water_subspecs(raw_mm_ref);
            end

%%          %%% 1D. GET REFERENCE DATA %%%
            if MRSCont.flags.hasRef
                ref_ll = MRSCont.opts.MultipleSpectra.ref(ll);
                raw_ref = MRSCont.raw_ref{ref_ll,kk};              % Get the kk-th dataset

                % Combine SPECIAL sub-spectra
                if MRSCont.flags.isSPECIAL
                    raw_ref = combine_special_subspecs(raw_ref);
                end

                if raw_ref.averages > 1 && raw_ref.flags.averaged == 0
                    [raw_ref,fs,phs]                 = op_alignAverages(raw_ref, 1, 'n');
                    badAverages=find(abs(fs)>6);
                    goodAverages=find(abs(fs)<6); 
                    if ~isempty(badAverages)
                        fs(badAverages) =[];
                        phs(badAverages) =[];
                        raw_ref.AveragesToKeep = goodAverages;
                        raw_ref.fids=raw_ref.fids(:,goodAverages,:,:);
                        raw_ref.specs=fftshift(ifft(raw_ref.fids,[],raw_ref.dims.t),raw_ref.dims.t);
                        raw_ref.sz=size(raw_ref.fids);
                        raw_ref.averages=length(goodAverages);
                    end
                    raw_ref                       = op_averaging(raw_ref);              % Average
                    raw_ref.specReg{1}.fs              = fs; % save align parameters
                    raw_ref.specReg{1}.phs             = phs; % save align parameters
                else
                    raw_ref.flags.averaged    = 1;
                    raw_ref.dims.averages     = 0;
                end

                raw_ref = op_combine_water_subspecs(raw_ref);                
            end

%%           %%% 1E. GET SHORT-TE WATER DATA %%%
             % And do the processing
             if MRSCont.flags.hasWater
                w_ll = MRSCont.opts.MultipleSpectra.w(ll);
                raw_w                           = MRSCont.raw_w{w_ll,kk};                % Get the kk-th dataset

                % Combine SPECIAL sub-spectra
                if MRSCont.flags.isSPECIAL
                    raw_w = combine_special_subspecs(raw_w);
                end

                if raw_w.averages > 1 && raw_w.flags.averaged == 0
                    [raw_w,fs,phs]                 = op_alignAverages(raw_w, 1, 'n');
                    badAverages=find(abs(fs)>6);
                    goodAverages=find(abs(fs)<6); 
                    if ~isempty(badAverages)
                        fs(badAverages) =[];
                        phs(badAverages) =[];
                        raw_w.AveragesToKeep = goodAverages;
                        raw_w.fids=raw_w.fids(:,goodAverages,:,:);
                        raw_w.specs=fftshift(ifft(raw_w.fids,[],raw_w.dims.t),raw_w.dims.t);
                        raw_w.sz=size(raw_w.fids);
                        raw_w.averages=length(goodAverages);
                    end
                    raw_w                       = op_averaging(raw_w);              % Average
                    raw_w.specReg{1}.fs              = fs; % save align parameters
                    raw_w.specReg{1}.phs             = phs; % save align parameters
                else
                    raw_w.flags.averaged    = 1;
                    raw_w.dims.averages     = 0;
                end

                if raw_w.subspecs > 1
                    raw_w = op_combine_water_subspecs(raw_w);
                end
                if ~MRSCont.flags.isMRSI
                    [raw_w,~]                       = op_eccKlose(raw_w, raw_w);        % Klose eddy current correction
                else
                    [raw_w,~]=op_autophase(raw_w,2,2*4.68);
                end
                [raw_w,~]                       = op_ppmref(raw_w,4.6,4.8,4.68);    % Reference to water @ 4.68 ppm
                raw_w.names = {'A'};
                MRSCont.processed.w{w_ll,kk}         = raw_w; % Save back to MRSCont container
            end

%%          %%% 2a. PHANTOM-SPECIFIC PRE-PROCESSING %%%
            % If this is phantom data (assuming room temperature), we want to
            % perform a few specific pre-processing steps.
            if MRSCont.flags.isPhantom
                % First, we undo phase cycling by dividing by the first data
% op_HadamardScans.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% out=op_addScans(in1,combMatrix);
% 
% DESCRIPTION:
% Add or subtract two scans together.
% 
% INPUTS:
% in        = Spectrum (in matlab structure format)
% combMatrix	 = How to combine the spectra
%
% OUTPUTS:
% out        = Result of adding inputs in1 and in2.  


function out=op_HadamardScans(in,combMatrix,name);

dim = in.dims.subSpecs;

if ~isempty(fieldnames(in))
    if dim == 2
        if length(combMatrix) == 2
            fids = combMatrix(1)*in.fids(:,1) + combMatrix(2)*in.fids(:,2);
        end
        if length(combMatrix) == 4
            fids = combMatrix(1)*in.fids(:,1) + combMatrix(2)*in.fids(:,2) + combMatrix(3)*in.fids(:,3)+ combMatrix(4)*in.fids(:,4);
        end
    end
end

%re-calculate Specs using fft
specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);

out=in;
if ~contains(in.names,name)
        out.fids=cat(dim,in.fids,fids);
        out.specs=cat(dim,in.specs,specs);
        out.sz=size(fids);            
        out.names{end+1} = name;
        out.subspecs = out.subspecs + 1;
    else
        ind = find(strcmp(out.names,name));
        out.fids(:,ind,:,:,:,:,:) = fids(:,1,:,:,:,:,:);
        out.specs(:,ind,:,:,:,:,:) = specs(:,1,:,:,:,:,:);
end




% op_averaging.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% out=op_averaging(in);
% 
% DESCRIPTION:
% Combine the averages in a scan by adding the averages together and then 
% dividing by the number of averages.
% 
% INPUTS:
% in	= input data in matlab structure format.
%
% OUTPUTS:
% out   = Output following averaging.  

function out=op_averaging(in);

if in.flags.averaged
    error('ERROR:  Averaging has already been performed!  Aborting!');
end

if in.dims.averages==0 || in.averages<2 || (length(in.sz)< in.dims.averages)
    %DO NOTHING
    warning('Just one average found. Returning input without modification!');
    %change the dims variables.
    dims.t=in.dims.t;
    if in.dims.coils>in.dims.averages
        dims.coils=in.dims.coils-1;
    else
        dims.coils=in.dims.coils;
    end
    dims.averages=0;
    if in.dims.subSpecs>in.dims.averages
        dims.subSpecs=in.dims.subSpecs-1;
    else
        dims.subSpecs=in.dims.subSpecs;
    end
    if in.dims.extras>in.dims.averages
        dims.extras=in.dims.extras-1;
    else
        dims.extras=in.dims.extras;
    end
    out=in;
    out.dims=dims;
    out.flags.averaged=1;
else

    %add the spectrum along the averages dimension;
    fids=sum(in.fids,in.dims.averages);
    fids=squeeze(fids);
    fids=fids/in.sz(in.dims.averages); %divide by number of averages;

    %re-calculate Specs using fft
    specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);

    %change the dims variables.
    if in.dims.t>in.dims.averages
        dims.t=in.dims.t-1;
    else
        dims.t=in.dims.t;
    end
    if in.dims.coils>in.dims.averages
        dims.coils=in.dims.coils-1;
    else
        dims.coils=in.dims.coils;
    end
    dims.averages=0;
    if in.dims.subSpecs>in.dims.averages
        dims.subSpecs=in.dims.subSpecs-1;
    else
        dims.subSpecs=in.dims.subSpecs;
    end
    if in.dims.extras>in.dims.averages
        dims.extras=in.dims.extras-1;
    else
        dims.extras=in.dims.extras;
    end


    %re-calculate the sz variable
    sz=size(fids);

    % Add NIfTI-MRS provenance
    % Generate fields for provenance
    fields.Method   = 'Signal averaging';
    fields.Details  = ['Classic signal averaging, dim = DIM_DYN'];
    in = op_add_analysis_provenance(in,fields);

    %FILLING IN DATA STRUCTURE
    out=in;
    out.fids=fids;
    out.specs=specs;
    out.sz=sz;
    out.dims=dims;
    out.averages=1;

    %FILLING IN THE FLAGS
    out.flags=in.flags;
    out.flags.writtentostruct=1;
    out.flags.averaged=1;

end

% philipsLoad.m
% Georg Oeltzschner, Johns Hopkins University 2018.
%
% USAGE:
% [data, header] = philipsLoad(filename);
% 
% DESCRIPTION:
% Reads in philips MRS data (.spar and .sdat files) using code adapted from 
% PhilipsRead.m, provided as part of the Gannet software package by Richard 
% Edden (gabamrs.com).
% 
% INPUTS:
% filename   = filename of Philips .sdat file to be loaded.
%
% OUTPUTS:
% data       = FID array.
% header     = Structure containing header information from SPAR file.

function [data, header] = philipsLoad(filename)

% Get the .spar filename
sparname = [filename(1:(end-4)) 'spar'];
% Populate the header information from the SPAR file
% Look for regular expression separated by a colon
fid_spar = fopen(sparname);
if fid_spar == -1
    sparname = [filename(1:(end-4)) 'SPAR']; %This seems to be a problem for some Linux based systems
    fid_spar = fopen(sparname);
end
while ~feof(fid_spar)
    tline = fgets(fid_spar); % get first line
    [tokens,matches] = regexp(tline,'([\w\[\].]*)\s*:\s*([-\w\s.\"\\:\.]*)','tokens','match');
        % When a matching string is found, parse the results into a struct
        if length(tokens) == 1
            fieldname = regexprep(tokens{1}{1}, '\[|\]',''); % delete invalid characters

            % Convert numbers to doubles, leave strings & empty lines alone
            if ~isnan(str2double(tokens{1}{2}))
                value = str2double(tokens{1}{2});
            else
                value = tokens{1}{2};
            end

            header.(fieldname) = value;

        end
end
fclose(fid_spar);

% Now open the SDAT file and read in the data
fid_sdat    = fopen(filename,'r','ieee-le');
sdat_length = length(fread(fid_sdat));
fclose(fid_sdat);
fid_sdat    = fopen(filename,'r','ieee-le');
data        = freadVAXG(fid_sdat,sdat_length,'float32');
fclose(fid_sdat);
% Reshape and save
if isfield(header, 'nr_of_slices_for_multislice') && header.nr_of_slices_for_multislice > 1
    data        = reshape(data, [2 header.samples header.rows header.nr_of_slices_for_multislice]);
    data        = squeeze(data(1,:,:,:)+1i*data(2,:,:,:));
else
    data        = reshape(data, [2 header.samples header.rows]);    
    data        = squeeze(data(1,:,:)+1i*data(2,:,:));
end
end

end
if dims.extras > 0 % Is a series
   out.extras = out.sz(dims.extras);
   extra_names = {};
   seq = {};
   for ex = 1 : out.sz(dims.extras)
       extra_names{ex} = ['Exp_' num2str(ex)];
